import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.F7eQ-ohH.js";const d="/bzygq/assets/94342e2c6c17465484c4c4a63b8a5424.BltaLUjt.png",q=JSON.parse('{"title":"索引体系与执行计划","description":"","frontmatter":{},"headers":[],"relativePath":"Java面试问题汇总/MongoDB/04-索引体系与执行计划.md","filePath":"Java面试问题汇总/MongoDB/04-索引体系与执行计划.md","lastUpdated":1788929995000}'),s={name:"Java面试问题汇总/MongoDB/04-索引体系与执行计划.md"};function i(p,t,n,u,l,c){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="索引体系与执行计划" tabindex="-1">索引体系与执行计划 <a class="header-anchor" href="#索引体系与执行计划" aria-label="Permalink to &quot;索引体系与执行计划&quot;">​</a></h1><p>MongoDB 查询性能的核心是索引和执行计划。没有合适索引时，数据库只能扫描集合中的大量文档，再逐条判断是否满足条件；有合适索引时，MongoDB 可以沿着有序索引结构定位较小范围，减少文档读取、排序和网络返回成本。索引不是“建了就快”，而是要和查询模式、排序方式、分页方式、字段选择性和写入成本一起看。</p><p>Java 后端面试里问 MongoDB 索引，一般不会停留在 createIndex 命令，而是追问：复合索引字段顺序为什么重要，数组字段为什么会变成多键索引，explain 里 IXSCAN 和 COLLSCAN 怎么看，为什么深分页慢，为什么索引不能无限加。这一章按“索引类型 -&gt; 复合索引设计 -&gt; 覆盖查询 -&gt; 执行计划 -&gt; 分页边界”的链路展开。</p><p><img src="'+d+'" alt="images/mongodb-index-explain-path.png"></p><p>images/mongodb-index-explain-path.png</p><h2 id="一、索引的基本作用与常见类型" tabindex="-1">一、索引的基本作用与常见类型 <a class="header-anchor" href="#一、索引的基本作用与常见类型" aria-label="Permalink to &quot;一、索引的基本作用与常见类型&quot;">​</a></h2><p>MongoDB 索引是集合数据的一份有序辅助结构，保存某个字段或多个字段的值以及指向原文档的引用。常规 B-tree 类索引可以支持等值匹配、范围查询和部分排序。没有索引时，查询可能是集合扫描；有合适索引时，数据库可以先扫描索引项，再按需要回表读取完整文档。</p><p>常见索引类型可以按用途理解：</p><ul><li>单字段索引用于最简单的字段过滤，例如按 userId 查询用户订单。</li><li>复合索引用于稳定的多条件查询和排序，例如按 userId + status 过滤，再按 createdAt 倒序。</li><li>多键索引用于数组字段，MongoDB 会为数组中的元素建立索引项，适合按标签、类型、嵌套数组元素查询。</li><li>唯一索引用于保证字段或字段组合不重复，例如用户邮箱、业务订单号、租户内唯一编码。</li><li>文本索引用于自管理部署里的 $text 字符串检索，但它不是搜索引擎，复杂全文检索更适合 MongoDB Search 或专门搜索系统。</li><li>地理空间索引用于地理位置查询，常见的是 2dsphere，用于附近门店、范围内地点、路径相关查询。</li><li>通配符索引用于字段不固定的灵活 schema，能支持未知字段查询，但通常不如针对固定字段的索引高效。</li><li>TTL 索引用于按时间自动过期删除文档，适合会话、日志、临时事件等有限保留数据。</li></ul><p>创建示例：</p><p>db.orders.createIndex({ userId: 1 }) db.orders.createIndex({ userId: 1, status: 1, createdAt: -1 }) db.users.createIndex({ email: 1 }, { unique: true }) db.articles.createIndex({ title: &quot;text&quot;, content: &quot;text&quot; }) db.stores.createIndex({ location: &quot;2dsphere&quot; }) db.events.createIndex({ expireAt: 1 }, { expireAfterSeconds: 0 }) db.products.createIndex({ &quot;attributes.$**&quot;: 1 })</p><p>索引的代价也要同时说清楚。每新增一条索引，写入、更新、删除都要维护对应索引项；索引占用存储和内存；低选择性字段上的索引可能收益有限；过多索引会让写多读少集合变慢。面试中比较稳的表达是：索引围绕高频查询模式设计，而不是围绕所有字段平均铺开。</p><h2 id="二、复合索引字段顺序与-esr-规则" tabindex="-1">二、复合索引字段顺序与 ESR 规则 <a class="header-anchor" href="#二、复合索引字段顺序与-esr-规则" aria-label="Permalink to &quot;二、复合索引字段顺序与 ESR 规则&quot;">​</a></h2><p>复合索引的字段顺序非常关键，因为索引内部先按第一个字段排序，在第一个字段相同的范围内再按第二个字段排序，依次类推。索引 { userId: 1, status: 1, createdAt: -1 } 和 { createdAt: -1, userId: 1, status: 1 } 不是同一回事，它们服务的查询模式完全不同。</p><p>例如订单列表接口经常这样查：</p><p>db.orders.find({ userId: 10086, status: &quot;PAID&quot;, createdAt: { $gte: ISODate(&quot;2026-06-01&quot;) } }).sort({ createdAt: -1 }).limit(20)</p><p>更自然的索引是：</p><p>db.orders.createIndex({ userId: 1, status: 1, createdAt: -1 })</p><p>userId 和 status 是等值条件，能先定位到较小范围；createdAt 既参与范围过滤，又承担排序方向，可以让数据库在用户和状态限定后的范围内按时间顺序读取。这个思路就是常说的 ESR 规则：Equality、Sort、Range。多数情况下，等值字段放前面；如果避免内存排序更关键，排序字段放在范围字段前；如果范围条件选择性极强，也可能让范围字段优先于排序字段，这时需要结合 explain 验证。</p><p>复合索引还涉及最左前缀。索引 { userId: 1, status: 1, createdAt: -1 } 可以较好支持只按 userId 查询，也可以支持按 userId + status 查询；但如果查询只有 status，或只有 createdAt，就跳过了最左字段，利用效率会明显下降。它也不适合全站按时间查最近订单，因为全站时间索引应更像 { createdAt: -1 } 或 { status: 1, createdAt: -1 }。</p><p>排序方向也要看整体匹配。复合索引中的升序和降序会影响多字段排序能否直接沿索引返回。单字段升降序差异通常不大，因为可以正向或反向扫描；多字段排序时，排序模式要么和索引方向一致，要么整体反向一致，才更容易直接利用索引顺序。比如 { userId: 1, createdAt: -1, _id: -1 } 适合用户维度下按时间倒序、再按 _id 倒序稳定排序。</p><h2 id="三、多键、唯一、文本、地理空间、通配符与-ttl-的边界" tabindex="-1">三、多键、唯一、文本、地理空间、通配符与 TTL 的边界 <a class="header-anchor" href="#三、多键、唯一、文本、地理空间、通配符与-ttl-的边界" aria-label="Permalink to &quot;三、多键、唯一、文本、地理空间、通配符与 TTL 的边界&quot;">​</a></h2><p>多键索引来自数组字段。对 tags: [&quot;java&quot;, &quot;mongodb&quot;] 建索引时，MongoDB 会为数组元素建立索引项，查询 tags: &quot;mongodb&quot; 可以利用该索引。多键索引的常见坑是数组元素可能很多，索引项会被放大；复合多键索引中，一个文档不能让复合索引里的多个字段同时都是数组，否则组合数量和语义都会失控。数组字段参与排序和覆盖查询时也有额外限制，面试中只要能说出“数组会展开成多个索引项，读能加速，写和索引体积会放大”就比较到位。</p><p>唯一索引既是性能结构，也是约束结构。{ email: 1 } 加 unique: true 可以防止两个用户使用同一个邮箱；复合唯一索引 { tenantId: 1, code: 1 } 可以表示“同一租户内编码唯一”。它的边界是：建索引前已有重复数据会导致创建失败；唯一索引对缺失字段和 null 的处理要谨慎；分片集合上的唯一约束还要考虑分片键前缀，否则无法保证全局语义。</p><p>文本索引用于 $text 查询，会按词项建立索引，而不是简单保存整段字符串。它适合轻量关键词搜索，不适合复杂相关性排序、中文分词定制、拼写纠错、向量语义检索等搜索引擎能力。课程里可以把它作为 MongoDB 内置搜索能力了解即可，不要把它等同于 Elasticsearch 或 Atlas Search。</p><p>地理空间索引用于位置数据。2dsphere 面向球面几何，常用于经纬度附近查询和多边形范围查询；2d 面向平面坐标，更多用于二维平面计算。实际后端项目里，附近门店、附近司机、范围内设备点位等场景通常会用 2dsphere，字段值应按 GeoJSON 或合法经纬度格式组织。它解决的是空间查询定位问题，不负责业务调度、路线规划或权限过滤，这些仍要在业务条件和其他索引字段中配合完成。</p><p>通配符索引使用 $**，用于字段名不固定的文档。例如商品扩展属性中，不同类目有不同属性字段，可以考虑对 attributes.$** 建通配符索引。它的边界也很明确：字段稳定时，针对具体字段建立普通索引通常更高效；通配符索引会覆盖更多字段，写入维护和存储成本更高；如果业务长期依赖大量未知字段查询，可能说明 schema 治理需要加强。</p><p>TTL 索引用于自动过期删除文档，例如：</p><p>db.login_sessions.createIndex( { expireAt: 1 }, { expireAfterSeconds: 0 } )</p><p>当 expireAt 到达后，后台任务会异步清理过期文档。它适合临时会话、验证码、事件日志、短期缓存落库等场景。不要把 TTL 当成精确定时任务，因为删除不是到点立即发生；也不要在核心业务数据上随意使用 TTL，否则可能因为字段错误或时间设置错误导致数据被自动清理。</p><h2 id="四、覆盖查询与回表成本" tabindex="-1">四、覆盖查询与回表成本 <a class="header-anchor" href="#四、覆盖查询与回表成本" aria-label="Permalink to &quot;四、覆盖查询与回表成本&quot;">​</a></h2><p>覆盖查询指的是：查询条件所需字段和返回结果所需字段都在同一个索引中，MongoDB 可以只读索引而不读取完整文档。这样能减少磁盘读取和文档反序列化成本，尤其适合列表页、存在性判断、轻量字段查询。</p><p>例如订单列表只需要 _id、createdAt 和 amount：</p><p>db.orders.createIndex({ userId: 1, status: 1, createdAt: -1, amount: 1 })</p><p>db.orders.find( { userId: 10086, status: &quot;PAID&quot; }, { _id: 0, createdAt: 1, amount: 1 } ).sort({ createdAt: -1 }).limit(20)</p><p>如果过滤字段、排序字段和返回字段都被索引覆盖，执行计划中可能只出现 IXSCAN，不需要 FETCH 回表。这里显式排除 _id 是因为 _id 默认会返回，如果索引没有包含 _id，它就会破坏覆盖查询。若业务确实需要 _id，可以把 _id 放进索引末尾，或者接受回表成本。</p><p>覆盖查询不是越追求越好。把大量返回字段都塞进复合索引，会让索引变宽，增加写入维护成本和内存占用。判断是否值得做覆盖，要看接口频率、返回字段大小、文档体积和写入比例。比如高频订单列表只返回少量字段，可以考虑覆盖；订单详情页本来就要完整文档，就没必要为覆盖而建立很宽的索引。</p><p>投影也不能替代索引。只返回少数字段能减少网络传输，但如果查询条件没有索引，MongoDB 仍然可能扫描大量文档后再投影。课程里要把两者区分开：索引减少扫描范围，投影减少返回宽度，覆盖查询则是在索引设计恰好包含过滤和返回字段时进一步减少回表。</p><h2 id="五、用-explain-读懂-ixscan、collscan-和扫描量" tabindex="-1">五、用 explain 读懂 IXSCAN、COLLSCAN 和扫描量 <a class="header-anchor" href="#五、用-explain-读懂-ixscan、collscan-和扫描量" aria-label="Permalink to &quot;五、用 explain 读懂 IXSCAN、COLLSCAN 和扫描量&quot;">​</a></h2><p>判断一个查询是否健康，不能只看本地测试耗时。缓存、数据量、机器负载都会影响耗时，而 explain(&quot;executionStats&quot;) 能给出更稳定的执行信号。常见关注点包括 winningPlan、stage、IXSCAN、COLLSCAN、FETCH、SORT、totalKeysExamined、totalDocsExamined、nReturned。</p><p>示例：</p><p>db.orders.find({ userId: 10086, status: &quot;PAID&quot; }).sort({ createdAt: -1 }) .limit(20) .explain(&quot;executionStats&quot;)</p><p>IXSCAN 表示扫描索引键，通常是好信号，但还要看扫描数量；COLLSCAN 表示集合扫描，意味着数据库正在读集合里的大量文档，除非集合很小或这是管理类低频操作，否则通常要警惕；FETCH 表示从索引定位后回表读取完整文档；SORT 如果不是沿索引完成，而是在内存或临时文件中排序，也可能成为慢点。</p><p>几个指标可以一起读：</p><ul><li>nReturned 是最终返回文档数，表示应用真正拿到多少条。</li><li>totalKeysExamined 是扫描的索引项数量，反映索引扫描范围。</li><li>totalDocsExamined 是检查过的文档数量，可能来自 COLLSCAN 或 FETCH。</li><li>健康查询通常希望扫描量和返回量接近，至少不能相差几个数量级。</li></ul><p>如果 nReturned = 20，但 totalKeysExamined = 200000，说明索引能用但范围太宽，可能是复合索引顺序不合适、过滤字段选择性不足、深分页跳过太多。若 totalDocsExamined = 200000 且出现 COLLSCAN，说明可能根本没有合适索引。若出现 IXSCAN + FETCH 且 totalDocsExamined 远大于返回数，说明索引先定位了一批候选，但大量文档还要回表过滤，可能需要把过滤字段补进复合索引。</p><p>执行计划不是为了追求所有查询都没有 FETCH 或所有查询都覆盖，而是为了确认数据库做的工作是否和业务返回量匹配。一个返回 20 条的在线接口，如果每次扫描几十万条，就是典型风险；一个每日离线统计任务扫描大量数据，则要看它是否错峰、是否可分批、是否应该预聚合或转入分析系统。</p><h2 id="六、深分页问题与索引设计的面试表达" tabindex="-1">六、深分页问题与索引设计的面试表达 <a class="header-anchor" href="#六、深分页问题与索引设计的面试表达" aria-label="Permalink to &quot;六、深分页问题与索引设计的面试表达&quot;">​</a></h2><p>MongoDB 分页最常见的性能坑是大 skip。skip(100000).limit(20) 的语义是跳过前 100000 条，再返回 20 条。即使命中索引，数据库也要沿着索引走过大量位置，页码越靠后，跳过成本越高。用户看到的是第 5001 页，数据库实际做的是从前面一路数过去。</p><p>典型慢分页如下：</p><p>db.orders.find({ userId: 10086, status: &quot;PAID&quot; }) .sort({ createdAt: -1 }) .skip(100000) .limit(20)</p><p>更适合消息流、订单列表、日志列表的方式是游标分页，也就是基于上一页最后一条记录继续往后查。为了保证排序稳定，常把业务时间字段和 _id 组合起来：</p><p>db.orders.createIndex({ userId: 1, status: 1, createdAt: -1, _id: -1 })</p><p>db.orders.find({ userId: 10086, status: &quot;PAID&quot;, $or: [ { createdAt: { $lt: ISODate(&quot;2026-06-30T12:00:00Z&quot;) } }, { createdAt: ISODate(&quot;2026-06-30T12:00:00Z&quot;), _id: { $lt: ObjectId(&quot;686232e07d5f1d4b5f2f1a11&quot;) } } ] }).sort({ createdAt: -1, _id: -1 }).limit(20)</p><p>这里 createdAt 负责主排序，_id 负责在相同时间下稳定排序。下一页不再靠 skip 跳过大量结果，而是从上一页边界继续扫描。它的代价是不能天然跳到任意页码，但多数移动端下拉、后台列表、消息流和订单流更需要“继续加载”，而不是精确跳页。</p><p>面试总结可以按下面这条线回答：</p><p>MongoDB 索引优化要先看查询模式。简单条件用单字段索引，稳定多条件和排序用复合索引，字段顺序按等值、排序、范围的思路设计，并结合 explain 验证。数组字段会形成多键索引，唯一索引用于约束，文本、地理空间、通配符、TTL 都有各自场景和边界。看执行计划时重点看 IXSCAN、COLLSCAN、FETCH、totalKeysExamined、totalDocsExamined 和 nReturned。深分页不要依赖大 skip，高频列表应改成基于上一页边界的游标分页。</p>',57)])])}const A=e(s,[["render",i]]);export{q as __pageData,A as default};
